def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    dp = [0] * (V + 1)

    for volume in volumes:
        for j in range(V, volume - 1, -1):
            dp[j] = max(dp[j], dp[j - volume] + volume)

    return V - dp[V]

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            for k in range(min(j, a[i - 1]) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    key = key.upper()
    ciphertext = ciphertext.upper()
    plaintext = []
    key_length = len(key)
    for i, char in enumerate(ciphertext):
        if char.isalpha():
            key_char = key[i % key_length]
            key_shift = ord(key_char) - ord('A')
            plaintext_char = chr((ord(char) - ord('A') - key_shift) % 26 + ord('A'))
            plaintext.append(plaintext_char)
        else:
            plaintext.append(char)
    return ''.join(plaintext)

def mod_inverse(a, b):
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    gcd, x, _ = extended_gcd(a, b)
    if gcd != 1:
        return None
    else:
        return x % b

